const today = new Date().toLocaleDateString('ko-KR', { timeZone:'Asia/Seoul' });
const SEARX = 'http://127.0.0.1:8888/search';
const queries = ['과기정통부 AI 인공지능 공모 접수중','중소벤처기업부 AI 지원사업 공고 모집','산업통상자원부 인공지능 공모 신청','NIPA 정보통신산업진흥원 AI 공모 접수','IRIS 범부처 인공지능 R&D 공모','AI 인공지능 정부 지원사업 공모 신청기간'];
const seen = new Set(); const results = [];
for(const q of queries){ try{ const r = await this.helpers.httpRequest({ method:'GET', url:SEARX, qs:{ q, format:'json', language:'ko-KR', safesearch:0 }, headers:{'User-Agent':'Mozilla/5.0'}, json:true, timeout:15000 }); for(const it of ((r&&r.results)||[]).slice(0,8)){ if(!it.url||seen.has(it.url)) continue; seen.add(it.url); results.push({ url:it.url, title:it.title||'', snippet:it.content||'' }); } }catch(e){} }
const top = results.slice(0,12); const docs=[];
for(const d of top){ let body=d.snippet||''; try{ const html = await this.helpers.httpRequest({ method:'GET', url:d.url, headers:{'User-Agent':'Mozilla/5.0'}, timeout:12000 }); const text = String(html).replace(/<[^>]+>/g,' ').replace(/&[a-z]+;/gi,' ').replace(/\s+/g,' ').trim(); if(text.length>200) body=text.slice(0,3500); }catch(e){} for(let i=0;i<body.length && i<2400;i+=800){ docs.push({ url:d.url, title:d.title, text:body.slice(i,i+800) }); } }
let chatId=''; try{ chatId = String(($input.first().json.chatId)||''); }catch(e){}
return [{ json:{ today, docs, found: results.length, chatId } }];

const inp = $input.first().json; const today=inp.today; const docs=inp.docs||[]; const chatId=inp.chatId||'';
const EMB='http://127.0.0.1:11434/api/embeddings'; const self=this;
async function embed(t){ const r=await self.helpers.httpRequest({ method:'POST', url:EMB, body:{ model:'nomic-embed-text', prompt:t }, json:true, timeout:20000 }); return (r&&r.embedding)||[]; }
function cos(a,b){ let d=0,na=0,nb=0; const n=Math.min(a.length,b.length); for(let i=0;i<n;i++){ d+=a[i]*b[i]; na+=a[i]*a[i]; nb+=b[i]*b[i]; } return d/(Math.sqrt(na)*Math.sqrt(nb)+1e-9); }
const query='오늘 '+today+' 기준 마감 전 접수중인 AI 인공지능 정부 공모사업 신청기간 주관기관 지원대상';
let qv=[]; try{ qv=await embed(query); }catch(e){}
const scored=[];
for(const doc of docs){ try{ const v=await embed(doc.text); scored.push(Object.assign({}, doc, { score: qv.length? cos(qv,v):0 })); }catch(e){ scored.push(Object.assign({}, doc, { score:0 })); } }
scored.sort((a,b)=>b.score-a.score);
const topK=scored.slice(0,8);
const ctx=topK.map((d,i)=>'['+(i+1)+'] 출처:'+d.url+' | 제목:'+d.title+'\n'+d.text).join('\n\n');
const sys='너는 정부지원사업 분석가다. 검색 컨텍스트에 실제로 있는 사실만 쓰고 없는 내용은 지어내지 않는다. 한국어로만 답한다.';
const user='오늘은 '+today+'. 아래 검색 컨텍스트에서 마감일이 명확히 지나지 않은(접수중이거나 마감일 미상 포함) AI 인공지능 정부 공모사업을 텔레그램 메시지용으로 정리하라. 최대 5개. 표나 HTML 태그 절대 쓰지 말고(텔레그램은 일반 텍스트), 각 사업을 아래 형식으로:\n\n📋 사업명\n🏛 주관: 기관명\n📅 기간: 신청기간(마감일)\n🎯 대상: 지원대상\n🔗 공고링크\n\n각 사업명은 📋 뒤에 공고 제목에서 실제 명칭을 반드시 채워라(빈칸 금지). 사업 사이는 빈줄로 구분하고, 목록 끝에 총평·요약 문장을 절대 붙이지 마라. 신청기간/대상이 컨텍스트에 없으면 정보없음. 접수중 AI 공모를 못 찾으면 "오늘 기준 접수중인 AI 공모를 찾지 못했어요."만 출력.\n\n[검색 컨텍스트]\n'+ctx;
const llmBody={ model:'qwen2.5:3b', messages:[{role:'system',content:sys},{role:'user',content:user}], temperature:0.2, stream:false };
return [{ json:{ today, llm_body: JSON.stringify(llmBody), chatId, found: inp.found } }];

const r=$input.first().json||{};
let content=(r.choices&&r.choices[0]&&r.choices[0].message&&r.choices[0].message.content)||'';
content=content.replace(/<[^>]+>/g,'').trim();
let today='',chatId=''; try{ const m=$('임베딩RAG').first().json; today=m.today; chatId=m.chatId||''; }catch(e){}
if(!content) content='오늘 기준 접수중인 AI 공모를 찾지 못했어요.';
const text='🔎 AI 정부공모 (기준일 '+today+')\n\n'+content+'\n\n※ 신청 전 공식 공고를 반드시 확인하세요.';
return [{ json:{ text: text.slice(0,4000), chatId, today } }];
